'use strict';
const DATA = window.PROJECT_SNAPSHOT;
const PHASES = [
  {name:'Foundation & coordination',short:'Foundation',description:'Configuration, paper-only guards, audit fixes, and shared contracts.'},
  {name:'Data & signals',short:'Data & signals',description:'Validated bars, momentum indicators, sizing, account reads, and the daily signal report.'},
  {name:'Backtesting & validation',short:'Backtesting',description:'Next-open fills, costs, benchmarks, split handling, and walk-forward research.'},
  {name:'Automatic paper trading',short:'Paper execution',description:'Independent risk checks, order lifecycle, protective exits, reconciliation, and the scheduler.'},
  {name:'Dashboard & operations',short:'Dashboard & operations',description:'Trading monitoring, notifications, security testing, and deployment safeguards.'},
  {name:'Research & evaluation',short:'Research & evaluation',description:'Untrusted research adapters and reproducible evaluation of paper results.'}
];
const LABELS = {'DONE':'Done','IN PROGRESS':'In progress','REVIEW':'In review','BLOCKED':'Owner input','READY':'Backlog'};
const CLASSES = {'DONE':'done','IN PROGRESS':'active','REVIEW':'review','BLOCKED':'blocked','READY':'ready'};
const content = document.querySelector('#content');
const state = {status:'all',phase:'all',owner:'all',search:''};
const repoURL = 'https://github.com/Ferrsir/semi-edge';
const openPRs = DATA.prs.filter(p=>p.state==='OPEN');
const dateFormat = new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',month:'short',day:'numeric',year:'numeric'});
const timeFormat = new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'});
const issueNumbers = t => Array.from(t.issue.matchAll(/#(\d+)/g), m=>Number(m[1]));
function el(tag, cls, text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=String(text);return n;}
function add(parent,...children){for(const c of children)if(c)parent.append(c);return parent;}
function link(text,url,cls=''){const n=el('a',cls,text);n.href=url;if(!url.startsWith('#')){n.target='_blank';n.rel='noopener';}return n;}
function button(text,action,cls=''){const b=el('button',cls,text);b.type='button';b.addEventListener('click',action);return b;}
function pill(status,label){return el('span','pill '+CLASSES[status],label||LABELS[status]);}
function agent(owner){return add(el('span','agent'),el('span','agent-dot '+(owner==='codex'?'codex':''),owner==='codex'?'C':owner==='claude'?'✳':'F'),el('span','',owner==='claude'?'Claude':owner==='codex'?'Codex':owner==='human'?'You':'Unassigned'));}
function taskPRs(t){return openPRs.filter(p=>new RegExp(`(?:^|/)(?:${issueNumbers(t).join('|') || 'NEVER'})(?:-|$)`).test(p.headRefName)||t.raw.includes('PR #'+p.number));}
function doneDependencies(t){if(/Phase/.test(t.dependencies))return false;return !Array.from(t.dependencies.matchAll(/\b(T\d+[a-z]?|A\d+)\b/g),m=>m[1]).some(id=>DATA.tasks.find(x=>x.id===id)?.status!=='DONE');}
function statusLabel(t){return t.status==='READY'?(doneDependencies(t)?'Ready':'Waiting on dependencies'):LABELS[t.status];}
function heading(title,subtitle,eyebrow='PROJECT WORKSPACE'){const h=el('div','page-heading');add(h,add(el('div'),el('div','greeting',eyebrow),el('h1','',title),el('p','',subtitle)),el('span','date-label',dateFormat.format(new Date(DATA.checked_at))));return h;}
function panel(title,body,action){const p=el('section','panel');add(p,add(el('div','panel-head'),el('h2','',title),action),body);return p;}
function taskDetails(t){const box=document.querySelector('#detail-body');box.replaceChildren();add(box,pill(t.status,statusLabel(t)),el('h2','',t.title),el('p','',t.raw));const dl=el('dl');for(const [label,value] of [['Task',t.id],['Owner',t.owner],['Phase',PHASES[t.phase].name],['Depends on',t.dependencies||'None']])add(dl,el('dt','',label),el('dd','',value));add(box,dl);for(const n of issueNumbers(t))add(box,link(`Open issue #${n} ↗`,`${repoURL}/issues/${n}`),el('br'));for(const p of taskPRs(t))add(box,link(`Review PR #${p.number} ↗`,p.url),el('br'));add(box,el('p','source-note','Source: coordination board. Opening a task here does not change GitHub or AGENTS.md.'));document.querySelector('#detail').showModal();}
function roadRow(phase,index){const tasks=DATA.tasks.filter(t=>t.phase===index&&!t.id.startsWith('H'));const done=tasks.filter(t=>t.status==='DONE').length;const row=el('div','road-row '+(index===1?'current':''));const middle=add(el('div','phase-content'),el('div','phase-title',phase.short),el('div','phase-meta',index===1?'CURRENT PHASE':index===0?'Foundation shipped · contracts in progress':'UPCOMING'));const track=el('div','progress');const fill=el('span');fill.style.width=(tasks.length?done/tasks.length*100:0)+'%';add(middle,add(track,fill));return add(row,el('span','phase-icon',String(index).padStart(2,'0')),middle,el('span','phase-count',`${done}/${tasks.length}`));}
function workItem(t){const item=el('div','work-item');const title=button(t.title,()=>taskDetails(t),'task-button work-title');add(item,add(el('div','work-meta'),el('span','mono',t.issue),el('span','','· '+PHASES[t.phase].short)),title,add(el('div','work-bottom'),agent(t.owner),pill(t.status,statusLabel(t))));return item;}
function overview(){add(content,heading('A clear view of what’s next.','Your roadmap, active work, and blockers. One shared picture.','SEMI-EDGE / PROJECT OVERVIEW'));
  const hero=el('section','hero');const text=add(el('div'),pill('IN PROGRESS','PHASE 1 · IN PROGRESS'),el('div','hero-title','Foundation shipped. Data & signals next.'),el('p','','The next milestone is a reproducible daily signal report. Data, account, and ingestion PRs are in review.'));add(hero,el('div','hero-number','01'),text,link('Explore roadmap ↗','#roadmap','hero-action'));hero.querySelector('a').removeAttribute('target');add(content,hero);
  const stats=el('div','stats');for(const [label,value,foot,icon] of [['In progress',DATA.tasks.filter(t=>t.status==='IN PROGRESS').length,'Active board items','↗'],['Awaiting review',DATA.tasks.filter(t=>t.status==='REVIEW').length,`${openPRs.length} open pull requests on GitHub`,'⇄'],['Completed',DATA.tasks.filter(t=>t.status==='DONE').length,'Completed board items, not a readiness score','✓'],['Needs you',2,'Setup decisions for credentialed runs','⚑']])add(stats,add(el('div','stat'),add(el('div','stat-top'),el('span','',label),el('span','stat-icon',icon)),el('div','stat-value',value),el('div','stat-foot',foot)));add(content,stats);
  const columns=el('div','two-col');const roads=el('div','panel-body');PHASES.forEach((p,i)=>add(roads,roadRow(p,i)));const left=el('div');add(left,panel('The roadmap',roads,link('View all phases ↗','#roadmap','text-link')));
  const active=el('div','panel-body');const work=DATA.tasks.filter(t=>t.status==='IN PROGRESS');work.forEach(t=>add(active,workItem(t)));if(!work.length)add(active,el('p','empty','No work is currently claimed.'));const right=el('div');add(right,panel('On the workbench',active));add(right,add(el('section','callout'),el('span','callout-icon','⚑'),add(el('div'),el('h3','','Two things need your input'),el('p','','Paper credentials and an earnings-data source. Offline development can continue.')),link('View setup ↗','#setup')));add(columns,left,right);add(content,columns);
  add(content,taskTable(DATA.tasks.filter(t=>t.status==='REVIEW'),'Ready for the next pair of eyes',link('Open review queue ↗','#reviews','text-link')));
  add(content,el('p','source-note','Counts reflect coordination-board items, which vary in scope. The project is not yet ready for unattended paper trading.'));
}
function taskTable(tasks,title,action){const table=el('table');const head=el('tr');for(const s of ['Task','Status','Owner','Issue / PR'])add(head,el('th','',s));add(table,add(el('thead'),head));const body=el('tbody');for(const t of tasks){const row=el('tr','clickable');const first=el('td');add(first,button(t.title,()=>taskDetails(t),'task-button task-name'),el('div','task-id',`${t.id} · ${PHASES[t.phase].short}`));const links=el('td');issueNumbers(t).forEach(n=>add(links,link(`#${n} `,`${repoURL}/issues/${n}`,'issue-link')));taskPRs(t).forEach(p=>add(links,el('br'),link(`PR #${p.number}`,p.url,'issue-link')));add(body,add(row,first,add(el('td'),pill(t.status,statusLabel(t))),add(el('td'),agent(t.owner)),links));}add(table,body);return panel(title,add(el('div','table-wrap'),tasks.length?table:el('p','empty','No tasks match these filters.')),action);}
function roadmap(){add(content,heading('The path to paper trading.','Six stages, with dependencies visible before the next step.'));PHASES.forEach((p,i)=>{const tasks=DATA.tasks.filter(t=>t.phase===i&&!t.id.startsWith('H'));const card=el('section','phase-card');const done=tasks.filter(t=>t.status==='DONE').length;add(card,add(el('div','phase-card-head'),el('span','phase-icon',String(i).padStart(2,'0')),add(el('div','phase-content'),el('h2','',p.name),el('p','',p.description)),pill(i===1?'IN PROGRESS':'READY',i===1?'Current phase':i===0?'Foundation + ongoing contracts':'Upcoming')));const track=el('div','progress');const fill=el('span');fill.style.width=(tasks.length?100*done/tasks.length:0)+'%';add(card,add(track,fill),el('p','section-caption',`${done} of ${tasks.length} board items completed`));const list=el('div','task-mini-list');tasks.forEach(t=>add(list,button(`${t.status==='DONE'?'✓':t.status==='REVIEW'?'⇄':t.status==='IN PROGRESS'?'↗':'○'} ${t.title}`,()=>taskDetails(t),'task-mini')));add(card,list);add(content,card);});}
function tasks(){add(content,heading('Everything on the board.','Find a task, see its owner, and follow it to the source.'));const filterbar=el('div','filterbar');const input=el('input','search');input.type='search';input.placeholder='Search tasks, issue numbers, or keywords…';input.setAttribute('aria-label','Search tasks');input.value=state.search;
  const phase=el('select');phase.setAttribute('aria-label','Filter by phase');add(phase,new Option('All phases','all'));PHASES.forEach((p,i)=>add(phase,new Option(`${i} · ${p.short}`,i)));phase.value=state.phase;
  const owner=el('select');owner.setAttribute('aria-label','Filter by owner');for(const [label,value] of [['All owners','all'],['Claude','claude'],['Codex','codex'],['You','human'],['Unassigned','unassigned']])add(owner,new Option(label,value));owner.value=state.owner;
  add(content,add(filterbar,input,phase,owner));const chips=el('div','chips');for(const [s,label] of [['all','All tasks'],['IN PROGRESS','In progress'],['REVIEW','In review'],['READY','Backlog'],['DONE','Done'],['BLOCKED','Owner input']])add(chips,button(label,()=>{state.status=s;tasksRedraw();},'chip '+(state.status===s?'on':'')));add(content,chips);const count=el('div','subtitle-count');const results=el('div');add(content,count,results);
  function update(){const query=state.search.toLowerCase();const filtered=DATA.tasks.filter(t=>(state.status==='all'||t.status===state.status)&&(state.phase==='all'||String(t.phase)===state.phase)&&(state.owner==='all'||t.owner===state.owner)&&`${t.title} ${t.issue} ${t.id} ${t.raw}`.toLowerCase().includes(query));count.textContent=`${filtered.length} of ${DATA.tasks.length} tasks`;results.replaceChildren(taskTable(filtered,'Project tasks'));}
  input.addEventListener('input',()=>{state.search=input.value;update();});phase.addEventListener('change',()=>{state.phase=phase.value;update();});owner.addEventListener('change',()=>{state.owner=owner.value;update();});update();
}
function tasksRedraw(){content.replaceChildren();tasks();}
function checks(p){const runs=p.statusCheckRollup||[];if(!runs.length)return 'No checks reported';if(runs.some(c=>['FAILURE','CANCELLED','TIMED_OUT','ACTION_REQUIRED','ERROR'].includes(c.conclusion||c.state)))return 'Checks need attention';if(runs.some(c=>c.status&&c.status!=='COMPLETED'||['PENDING','EXPECTED'].includes(c.state)))return 'Checks running';return 'Checks completed';}
function reviews(){add(content,heading('Keep the review loop moving.','Current open pull requests, their owners, and the next handoff.'));add(content,el('p','notice','Green CI is test evidence. Cross-provider review still determines whether a change is ready to merge.'));
  for(const p of openPRs){const card=el('section','review-card');const linked=DATA.tasks.find(t=>t.raw.includes('PR #'+p.number)||taskPRs(t).some(x=>x.number===p.number));const notes=p.number===36?'Claude has pushed the F-012 fix. Codex needs to review the updated data-layer revision.':p.number===39?'Claude has pushed the F-009 fix. Codex needs to re-review the raw account-flag validation.':p.number===45?'Offline ingestion is published. Claude cross-provider review is the next step.':p.number===43?'Dependency maintenance: inspect the lockfile change and CI before merging.':'Review the current revision and resolve findings on GitHub.';
    add(card,add(el('div','review-header'),el('span','mono',`PR #${p.number}`),pill('REVIEW',checks(p))),el('h2','',p.title),el('p','',notes),el('p','mono',`Head ${(p.headRefOid||'unknown').slice(0,7)} · ${p.headRefName}`),link('Open pull request ↗',p.url));if(linked)add(card,el('p','source-note',`Board task ${linked.id} · ${linked.owner}`));add(content,card);}
  if(!openPRs.length)add(content,el('p','empty','No open pull requests in this snapshot.'));
}
function readSetup(){try{return JSON.parse(localStorage.getItem('semi-edge-owner-checks')||'{}');}catch{return {};}}
function setup(){add(content,heading('A little input from you.','Engineering can continue offline while these connections are prepared.'));add(content,el('p','notice','Checkmarks below are private browser reminders. They do not update GitHub, connect an account, or confirm credentials work. Never enter API keys here.'));const saved=readSetup();
  const items=[['paper','Alpaca paper credentials','Create paper-only keys and configure them securely in your local environment. Needed for actual account reads, vendor-data integration, and later paper execution. Keep order submission disabled until deliberately enabled.','https://github.com/Ferrsir/semi-edge/issues/13','Required for credentialed runs'],['earnings','Choose an earnings-calendar source','Select a verified source for the three-session earnings blackout. No provider has been selected or verified yet. Automatic execution must fail closed without verified coverage.','https://github.com/Ferrsir/semi-edge/issues/20','Needed before automatic execution'],['discord','Discord notifications','Optional: prepare a webhook later, when notification delivery is implemented. Store it securely; the project dashboard does not collect it.','https://github.com/Ferrsir/semi-edge/issues/26','Optional · Phase 4'],['identity','Dedicated agent GitHub identity','Optional governance follow-up: separate agent permissions from your owner account, with least privilege.','https://github.com/Ferrsir/semi-edge/issues/5','Optional governance']];
  for(const [id,title,desc,url,badge] of items){const input=el('input');input.type='checkbox';input.id='setup-'+id;input.checked=!!saved[id];input.addEventListener('change',()=>{const value=readSetup();value[id]=input.checked;try{localStorage.setItem('semi-edge-owner-checks',JSON.stringify(value));toast('Personal checklist updated in this browser.');}catch{toast('Browser storage unavailable; checkmark is temporary.');}});const label=el('label');label.htmlFor=input.id;add(label,el('h2','',title));add(content,add(el('section','setup-card'),input,add(el('div'),pill('READY',badge),label,el('p','',desc),link('View related issue ↗',url))));}
}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',7000);}
function render(){const key=location.hash.slice(1)||'overview';const pages={overview,roadmap,tasks,reviews,setup};const page=pages[key]?key:'overview';document.querySelectorAll('[data-page]').forEach(n=>{const active=n.dataset.page===page;n.classList.toggle('selected',active);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});document.querySelector('#breadcrumb').textContent={overview:'Overview',roadmap:'Phase roadmap',tasks:'All tasks',reviews:'Review queue',setup:'Your setup'}[page];content.replaceChildren();if(Date.now()-Date.parse(DATA.checked_at)>24*60*60*1000)add(content,el('div','stale','This snapshot is more than 24 hours old. Check GitHub for current status; refreshing the page does not fetch new project data.'));pages[page]();window.scrollTo(0,0);}
document.querySelector('#nav-count').textContent=DATA.tasks.length;document.querySelector('#nav-reviews').textContent=openPRs.length;document.querySelector('#footer-date').textContent='Checked '+timeFormat.format(new Date(DATA.checked_at));document.querySelector('#refresh-info').addEventListener('click',()=>{const box=document.querySelector('#detail-body');box.replaceChildren();add(box,el('h2','','Refresh the project snapshot'),el('p','','This private dashboard uses a saved snapshot, not a live GitHub connection. No access token is stored in the browser.'),el('p','','Ask Claude or Codex: “Refresh the project-status dashboard from AGENTS.md and GitHub, then republish it.” The refresh script and source are documented in the dashboard repository.'),el('p','','Use Export status to download the current snapshot. Opening the GitHub links shows the latest source state.'),link('Open current GitHub issues ↗',repoURL+'/issues'));document.querySelector('#detail').showModal();});document.querySelector('#export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(DATA,null,2)],{type:'application/json'});const a=el('a');a.href=URL.createObjectURL(blob);a.download='semi-edge-project-status.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Project snapshot exported.');});document.querySelector('#close-dialog').addEventListener('click',()=>document.querySelector('#detail').close());document.querySelector('#detail').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close();});window.addEventListener('hashchange',render);render();
